78	    gap: 1px;
79	  }
80	  .mini-cell { background: transparent; }
81	  button {
82	    font: inherit;
83	    color: var(--text);
84	    background: var(--panel);
85	    border: 1px solid var(--line);
86	    padding: 8px 12px;
87	    cursor: pointer;
88	  }
89	  button:hover { border-color: var(--muted); }
90	  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
91	  .p-I { background: #22c7e0; }
92	  .p-O { background: #f2c511; }
93	  .p-T { background: #9b4dca; }
