99	</head>
100	<body>
101	<div class="game">
102	  <div class="board-wrap">
103	    <div class="board" data-testid="board" id="board"></div>
104	    <div class="overlay" id="overlay" hidden>Game over</div>
105	  </div>
106	  <div class="side">
107	    <div class="box">
108	      <div class="label">Score</div>
109	      <div class="value" data-testid="score" id="score">0</div>
110	    </div>
111	    <div class="box">
112	      <div class="label">Level</div>
113	      <div class="value" data-testid="level" id="level">1</div>
114	    </div>
115	    <div class="box">
116	      <div class="label">Lines</div>
117	      <div class="value" data-testid="lines" id="lines">0</div>
118	    </div>
119	    <div class="box">
120	      <div class="label">Next</div>
121	      <div class="next-list" id="next"></div>
122	    </div>
123	    <button type="button" id="new-game">New game</button>
124	    <div class="help">
125	      ← → move<br>
126	      ↓ soft drop<br>
127	      Space hard drop<br>
128	      ↑ rotate
129	    </div>
130	  </div>
131	</div>
132	
133	<script>
134	(function () {
135	  "use strict";
136	
137	  var ROWS = 20;
138	  var COLS = 10;
139	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
140	  var PREVIEW = 3;
141	  var GRAVITY_MS = 1000;
142	  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
143	  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move restarts the delay
144	
145	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
146	  var SHAPES = {
147	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
148	    O: { m: ["OO", "OO"], row: 0, col: 4 },
149	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
150	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
151	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
152	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
153	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
154	  };
155	
156	  // ---- State ----
157	  var board;        // board[row][col] = "" or piece letter
158	  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
159	  var next;         // upcoming piece letters, soonest first
160	  var scripted;     // true while `next` comes from a test-supplied queue
161	  var bag = [];
162	  var score, level, lines, status;
163	  var timer = null;
164	
165	  function emptyBoard() {
166	    var b = [];
167	    for (var r = 0; r < ROWS; r++) {
168	      var row = [];
169	      for (var c = 0; c < COLS; c++) row.push("");
170	      b.push(row);
171	    }
172	    return b;
173	  }
174	
175	  function randomType() {
176	    if (bag.length === 0) {
177	      bag = TYPES.slice();
178	      for (var i = bag.length - 1; i > 0; i--) {
179	        var j = Math.floor(Math.random() * (i + 1));
180	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
181	      }
182	    }
183	    return bag.pop();
184	  }
185	
186	  function fillPreview() {
187	    if (scripted) return;
188	    while (next.length < PREVIEW) next.push(randomType());
189	  }
190	
191	  function shapeCells(matrix, row, col) {
192	    var cells = [];
193	    for (var r = 0; r < matrix.length; r++) {
194	      for (var c = 0; c < matrix[r].length; c++) {
195	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
196	      }
197	    }
198	    return cells;
199	  }
200	
201	  function fits(matrix, row, col) {
202	    var cells = shapeCells(matrix, row, col);
203	    for (var i = 0; i < cells.length; i++) {
204	      var r = cells[i][0], c = cells[i][1];
205	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
206	      if (board[r][c] !== "") return false;
207	    }
208	    return true;
209	  }
210	
211	  function spawn() {
212	    if (next.length === 0) scripted = false;
213	    fillPreview();
214	    var type = next.shift();
215	    fillPreview();
216	    var s = SHAPES[type];
217	    var piece = {
218	      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
219	      lockTicks: 0,   // consecutive gravity steps spent unable to fall
220	      lockResets: 0   // lifetime count of lock-delay restarts
221	    };
222	    if (!fits(piece.matrix, piece.row, piece.col)) {
223	      current = null;
224	      status = "over";
225	      stopTimer();
226	      return;
227	    }
228	    current = piece;
229	  }
230	
231	  function lock() {
232	    var cells = shapeCells(current.matrix, current.row, current.col);
233	    for (var i = 0; i < cells.length; i++) {
234	      board[cells[i][0]][cells[i][1]] = current.type;
235	    }
236	    current = null;
237	    spawn();
238	  }
239	
240	  function tryMove(dr, dc) {
241	    if (!current) return false;
242	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
243	    current.row += dr;
244	    current.col += dc;
245	    return true;
246	  }
247	
248	  // The single gravity step, used by the real timer, tick() and soft drop.
249	  // A step that cannot move the piece down counts one tick of lock delay.
250	  function gravityStep() {
251	    if (status !== "running" || !current) return;
252	    if (tryMove(1, 0)) {
253	      current.lockTicks = 0;
254	      return;
255	    }
256	    current.lockTicks++;
257	    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
258	  }
259	
260	  // Left/right. A move made while the lock delay is running restarts it,
261	  // up to MAX_LOCK_RESETS times per piece.
262	  function shift(dc) {
263	    var resting = current.lockTicks > 0;
264	    if (!tryMove(0, dc)) return;
265	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
266	      current.lockResets++;
267	      current.lockTicks = 0;
268	    }
269	  }
270	
271	  // Clockwise rotation. Tries the rotated shape in place, then shifted
272	  // sideways; if none fit, the piece is left unchanged.
273	  function rotateCW() {
274	    if (!current) return;
275	    var m = current.matrix;
276	    var n = m.length;
277	    var rotated = [];
278	    for (var r = 0; r < n; r++) {
279	      var line = "";
280	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
281	      rotated.push(line);
282	    }
283	    var kicks = [0, -1, 1, -2, 2];
284	    for (var i = 0; i < kicks.length; i++) {
285	      var nc = current.col + kicks[i];
286	      if (fits(rotated, current.row, nc)) {
287	        current.matrix = rotated;
288	        current.col = nc;
289	        return;
290	      }
291	    }
292	  }
293	
294	  // Hard drop skips the lock delay.
295	  function hardDrop() {
296	    if (!current) return;
297	    while (tryMove(1, 0)) {}
298	    lock();
299	  }
300	
301	  function applyInput(action) {
302	    if (status !== "running" || !current) return;
303	    switch (action) {
304	      case "left": shift(-1); break;
305	      case "right": shift(1); break;
306	      case "softDrop": gravityStep(); break;
307	      case "hardDrop": hardDrop(); break;
308	      case "rotateCW":
309	      case "rotate": rotateCW(); break;
310	    }
311	  }
312	
313	  // ---- Timer ----
314	  function stopTimer() {
315	    if (timer !== null) { clearInterval(timer); timer = null; }
316	  }
317	
318	  function startTimer() {
319	    stopTimer();
320	    timer = setInterval(function () {
321	      gravityStep();
322	      render();
323	    }, GRAVITY_MS);
324	  }
325	
326	  // ---- Rendering (synchronous) ----
327	  var boardEl = document.getElementById("board");
328	  var nextEl = document.getElementById("next");
329	  var overlayEl = document.getElementById("overlay");
330	  var scoreEl = document.getElementById("score");
331	  var levelEl = document.getElementById("level");
332	  var linesEl = document.getElementById("lines");
333	  var cellEls = [];
334	
335	  (function buildBoard() {
336	    for (var r = 0; r < ROWS; r++) {
337	      cellEls.push([]);
338	      for (var c = 0; c < COLS; c++) {
339	        var el = document.createElement("div");
340	        el.className = "cell";
341	        el.setAttribute("data-testid", "cell");
342	        el.setAttribute("data-row", String(r));
343	        el.setAttribute("data-col", String(c));
344	        el.setAttribute("data-filled", "false");
345	        el.setAttribute("data-piece", "");
346	        boardEl.appendChild(el);
347	        cellEls[r].push(el);
348	      }
349	    }
350	  })();
351	
352	  function paintCell(el, piece) {
353	    el.className = piece ? "cell p-" + piece : "cell";
354	    el.setAttribute("data-filled", piece ? "true" : "false");
355	    el.setAttribute("data-piece", piece);
356	  }
357	
358	  function renderNext() {
359	    nextEl.textContent = "";
360	    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
361	      var type = next[i];
362	      var m = SHAPES[type].m;
363	      var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
364	      var mini = document.createElement("div");
365	      mini.className = "mini";
366	      for (var r = 0; r < 2; r++) {
367	        for (var c = 0; c < 4; c++) {
368	          var ch = m[r + offset] && m[r + offset][c];
369	          var cell = document.createElement("div");
370	          cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
371	          mini.appendChild(cell);
372	        }
373	      }
374	      nextEl.appendChild(mini);
375	    }
376	  }
377	
378	  function render() {
379	    var view = board.map(function (row) { return row.slice(); });
380	    if (current) {
381	      var cells = shapeCells(current.matrix, current.row, current.col);
382	      for (var i = 0; i < cells.length; i++) {
383	        view[cells[i][0]][cells[i][1]] = current.type;
384	      }
385	    }
386	    for (var r = 0; r < ROWS; r++) {
387	      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
388	    }
389	    scoreEl.textContent = String(score);
390	    levelEl.textContent = String(level);
391	    linesEl.textContent = String(lines);
392	    overlayEl.hidden = status !== "over";
393	    renderNext();
394	  }
395	
396	  // ---- Game control ----
397	  function validTypes(queue) {
398	    if (!Array.isArray(queue)) return [];
399	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
400	  }
401	
402	  function newGame(queue) {
403	    board = emptyBoard();
404	    score = 0;
405	    level = 1;
406	    lines = 0;
407	    status = "running";
408	    current = null;
409	    bag = [];
410	    if (Array.isArray(queue)) {
411	      next = validTypes(queue);
412	      scripted = true;
413	    } else {
414	      next = [];
415	      scripted = false;
416	    }
417	    spawn();
418	    startTimer();
419	    render();
420	  }
421	
422	  function setQueue(queue) {
423	    next = validTypes(queue);
424	    scripted = true;
425	    render();
426	  }
427	
428	  function setBoard(rows) {
429	    var b = emptyBoard();
430	    for (var r = 0; r < ROWS; r++) {
431	      var line = (rows && rows[r]) || "";
432	      for (var c = 0; c < COLS; c++) {
433	        var ch = line.charAt(c);
434	        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
435	      }
436	    }
437	    board = b;
438	    render();
439	  }
440	
441	  function getBoard() {
442	    return board.map(function (row) {
443	      return row.map(function (v) { return v || "."; }).join("");
444	    });
445	  }
446	
447	  function getState() {
448	    var cur = null;
449	    if (current) {
450	      var cells = shapeCells(current.matrix, current.row, current.col);
451	      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
452	      cur = { type: current.type, cells: cells };
453	    }
454	    return {
455	      current: cur,
456	      next: next.slice(),
457	      score: score,
458	      level: level,
459	      lines: lines,
460	      status: status
461	    };
462	  }
463	
464	  function tick(n) {
465	    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
466	    for (var i = 0; i < steps; i++) gravityStep();
467	    render();
468	  }
469	
470	  window.__tetris = {
471	    newGame: newGame,
472	    setQueue: setQueue,
473	    setBoard: setBoard,
474	    tick: tick,
475	    input: function (action) { applyInput(action); render(); },
476	    getBoard: getBoard,
477	    getState: getState
478	  };
479	
480	  // ---- Keyboard ----
481	  var KEYS = {
482	    ArrowLeft: "left",
483	    ArrowRight: "right",
484	    ArrowDown: "softDrop",
485	    " ": "hardDrop",
486	    ArrowUp: "rotateCW"
487	  };
488	
489	  document.addEventListener("keydown", function (e) {
490	    var action = KEYS[e.key];
491	    if (!action) return;
492	    e.preventDefault();
493	    window.__tetris.input(action);
494	  });
495	
496	  document.getElementById("new-game").addEventListener("click", function (e) {
497	    e.currentTarget.blur();
498	    newGame();
499	  });
500	
501	  newGame();
502	})();
503	</script>
504	</body>
505	</html>
